type CaptureCommandResultOptions = {
  argv: string[];
  producer: string;
  binding: WorkContextBinding;
  stateRoot?: string;
  cwd?: string;
  now?: Clock;
};

async function captureCommandResult(options: CaptureCommandResultOptions): Promise<ToolResultReceipt> {
  const clock = options.now ?? nowIso;
  const binding = validateBinding(options.binding, clock);
  const producer = validateProducer(options.producer);
  const createdAt = clock();
  const createdAtMs = Date.parse(createdAt);
  if (!Number.isFinite(createdAtMs)) {
    throw new ToolResultError("TOOL_RESULT_INVALID_REQUEST", "now must return an ISO date-time");
  }
  const expiresAt = new Date(createdAtMs + RETENTION_MS).toISOString();
  const paths = await prepareStore(options.stateRoot);
  const temporaryDirectory = join(paths.temporary, `.capture-${randomUUID()}`);
  await mkdir(temporaryDirectory, { mode: 0o700 });

type WorkContextBinding = {
  version: 1;
  id: string;
  status: "active" | "superseded";
  host: string;
  session_id: string;
  bound_at: string;
  last_seen_at: string;
  expires_at: string;
  collaboration_space: WorkspaceRef;
  provenance: {
    kind: "host_lifecycle" | "operator_rebind";
    lifecycle: string;
    observed_cwd: string;
  };
  superseded_by?: string;
  superseded_at?: string;
};

export type {
  BindWorkContextOptions,
  RequireWorkContextBindingOptions,
  SupersedeWorkContextBindingOptions,
  WorkContextBinding,
  WorkContextBindingView,
  WorkContextErrorCode,
} from "./binding.ts";

